{
  "name": "@viniciuspoa2/opencode-cost-guard",
  "version": "0.1.2",
  "description": "Warns OpenCode users when session context and model choice may increase cost.",
  "license": "MIT",
  "author": "Commitgeist",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/commitgeist/opencode-cost-guard.git"
  },
  "bugs": {
    "url": "https://github.com/commitgeist/opencode-cost-guard/issues"
  },
  "homepage": "https://github.com/commitgeist/opencode-cost-guard#readme",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun build ./src/index.ts --outdir ./dist --target bun --format esm && tsc -p tsconfig.build.json",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run typecheck && bun run test && bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cost",
    "tokens",
    "context"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.1.50"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.50",
    "@types/bun": "^1.3.10",
    "typescript": "^5.9.3"
  },
  "engines": {
    "bun": ">=1.2.0"
  }
}
